import zipfile, re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
RNS = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'

z = zipfile.ZipFile('budget.xlsx')
wb = ET.fromstring(z.read('xl/workbook.xml'))
sheets = wb.findall('.//m:sheets/m:sheet', NS)

ss = []
if 'xl/sharedStrings.xml' in z.namelist():
    sroot = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in sroot.findall('m:si', NS):
        txt = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        ss.append(txt)

rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels')) if 'xl/_rels/workbook.xml.rels' in z.namelist() else []
relmap = {r.get('Id'): r.get('Target') for r in rels}

def col_to_idx(letters):
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - 64)
    return n

grand = 0.0
for s in sheets:
    name = s.get('name')
    target = relmap.get(s.get(RNS))
    path = ('xl/' + target) if target and not target.startswith('/') else (target[1:] if target else None)
    root = ET.fromstring(z.read(path))
    rows = root.findall('.//m:sheetData/m:row', NS)
    grid = []
    for row in rows:
        r = int(row.get('r'))
        cells = {}
        for c in row.findall('m:c', NS):
            ref = c.get('r')
            col = col_to_idx(re.match(r'[A-Z]+', ref).group(0))
            t = c.get('t')
            v = c.find('m:v', NS)
            val = None
            if v is not None:
                val = v.text
                if t == 's':
                    val = ss[int(val)]
                elif t == 'b':
                    val = (val == '1')
                elif t == 'n':
                    val = float(val)
            else:
                isel = c.find('m:is', NS)
                if isel is not None:
                    val = ''.join(x.text or '' for x in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            cells[col] = val
        grid.append((r, cells))
    print(f"\n=== Sheet: {name} ===")
    for r, cells in grid:
        print(f"Row {r}:", cells)
    col_sums = {}
    for r, cells in grid:
        for col, val in cells.items():
            if isinstance(val, (int, float)):
                col_sums[col] = col_sums.get(col, 0.0) + val
    print("Column sums:", {f"col{int(k)}": v for k, v in sorted(col_sums.items())})
    grand += sum(col_sums.values())

print(f"\nGRAND TOTAL (sum of all numeric cells) = {grand}")

